/** Record the stored deferral in the audit file, naming the claim like every claim line, then the date it is
 *  deferred until. */
public class AuditClaimDeferred {
    public void audit(@Val DeferInput input, @Val Claim loaded, @Val ClaimResponse saved, PersonRepository people,
            Audit audit) {
        var person = people.find(loaded.sheetId(), loaded.personId());
        audit.record("CLAIM_DEFERRED sheet=" + loaded.sheetId() + " by=" + input.user()
                + " person=" + person.name() + " amount=" + saved.amount() + " date=" + saved.date()
                + (saved.number() != null ? " number=" + saved.number() : "")
                + " until=" + saved.deferredUntil());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.PersonRepository;
