import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.Dues;
import net.officefloor.hq.app.statement.LateCharge;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each claim's status log: one line per status it has had, oldest first, as
 *  <STATUS> by <user> on <date> due=<due>, the date being the sheet's today when the status was given and the due
 *  the claim's due as its row showed it then (n/a when it had no figure). */
@Repository
public class ClaimLogRepository {

    private final JdbcTemplate jdbc;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final SettingRepository settings;
    private final SheetRepository sheets;

    public ClaimLogRepository(JdbcTemplate jdbc, ClaimRepository claims, PersonRepository people,
            RateRepository rates, SettingRepository settings, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Log the claim's status as stored now, given by the user, with its due as its row shows it now. */
    public void record(Claim claim, String user) {
        String sheetId = claim.sheetId();
        Claim now = claims.find(sheetId, claim.id());
        var person = people.find(sheetId, now.personId());
        BigDecimal due = Dues.shown(now, person.grades(), rates, settings.floor(sheetId),
                LateCharge.of(sheetId, settings, sheets, claims));
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due) VALUES (?, ?, ?, ?, ?, ?)",
                sheetId, now.id(), now.status().name(), user, sheets.today(sheetId), due);
    }

    /** The log lines of every claim on the sheet, by claim id, oldest first. */
    public Map<Long, List<String>> lines(String sheetId) {
        Map<Long, List<String>> lines = new HashMap<>();
        jdbc.query("SELECT * FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
            LocalDate on = rs.getObject("on_date", LocalDate.class);
            BigDecimal due = rs.getBigDecimal("due");
            lines.computeIfAbsent(rs.getLong("claim_id"), k -> new ArrayList<>())
                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                            + (on != null ? on.toString() : "") + " due=" + (due != null ? due.toPlainString() : "n/a"));
        }, sheetId);
        return lines;
    }

    /** Each logged claim's status at the end of the day given, by claim id, as its log records it: the last status
     *  given on or before that day (one given while the sheet had no today counts as given by then); null when every
     *  status it has was given after it (it was added later). A claim with no log is not in the map. */
    public Map<Long, ClaimStatus> statusesAt(String sheetId, LocalDate end) {
        Map<Long, ClaimStatus> statuses = new HashMap<>();
        jdbc.query("SELECT * FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
            LocalDate on = rs.getObject("on_date", LocalDate.class);
            long claimId = rs.getLong("claim_id");
            if (on == null || !on.isAfter(end)) {
                statuses.put(claimId, ClaimStatus.valueOf(rs.getString("status")));
            } else {
                statuses.putIfAbsent(claimId, null);
            }
        }, sheetId);
        return statuses;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: the amount is required, a
 *  number with up to two decimals, below 0.00 only for a correction, which names (by its number: a whole number, or <period name>-<n> / X-<n>) the claim it
 *  corrects, and only a correction names one; the date, when given, is a real yyyy-mm-dd date. */
public class ValidateClaim {
    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body) throws InvalidClaimException {
        body.set(check(request));
    }

    /** The claim form's rules, shared by every way a claim is added (the paste box checks each line by them). */
    static ClaimInput check(ClaimRequest request) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (amount.isEmpty()) {
            throw new InvalidClaimException("An amount is required.");
        }
        if (!amount.matches("-?\\d{1,12}(\\.\\d{1,2})?")) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (!rawCorrects.isEmpty()) {
            if (rawCorrects.matches("\\d{1,9}")) {
                corrects = String.valueOf(Integer.parseInt(rawCorrects));
            } else if (rawCorrects.matches(".{1,200}-\\d{1,9}")) {
                corrects = rawCorrects;
            } else {
                throw new InvalidClaimException("The claim corrected must be named by its number.");
            }
        }
        if (value.signum() < 0 && corrects == null) {
            throw new InvalidClaimException(
                    "A negative amount is a correction: name the number of the SETTLED claim it corrects.");
        }
        if (value.signum() >= 0 && corrects != null) {
            throw new InvalidClaimException("Only a correction (a negative amount) names a claim it corrects.");
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            if (!rawDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
                throw new InvalidClaimException("The date must be a date (yyyy-mm-dd).");
            }
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("The date must be a real date (yyyy-mm-dd).");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        if (note.length() > 1000) {
            throw new InvalidClaimException("A note is at most 1000 characters.");
        }
        return new ClaimInput(request.user().trim(), value, date, note, corrects);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidClaim {
    public void handle(@Parameter InvalidClaimException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
-- A claim's proofs count, raised by one at a time (never on a SETTLED or VOID claim). A claim whose due is above the
-- sheet's proof threshold in force on its date cannot be settled or approved while it has none. The proof threshold
-- is a dated setting (setting_value key proof-threshold; blank: none).
ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
-- A claim may be a correction: a negative amount that names, by number, a SETTLED claim of the same person it
-- corrects (null: not a correction). The amount may now be below 0.00 for a correction; the column is rebuilt to
-- drop its 0.00-or-more check.
ALTER TABLE claim ADD COLUMN corrects INT;
ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(14, 2);
UPDATE claim SET amount_signed = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;

